code='''def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]

    # The design is mirrored across the main diagonal; most covered cells
    # can be copied from their transposed position.
    for r in range(n):
        for c in range(n):
            if original[r][c] == 6 and original[c][r] != 6:
                out[r][c] = original[c][r]

    # Repeated rows provide values where both transposed positions are covered.
    for r in range(n):
        for c in range(n):
            if out[r][c] != 6:
                continue
            values = []
            for k in range(n):
                if k == r or original[k][c] == 6:
                    continue
                shared = [(a, b) for a, b in zip(original[r], original[k]) if a != 6 and b != 6]
                if len(shared) >= 10 and all(a == b for a, b in shared):
                    values.append(original[k][c])
            if values and all(v == values[0] for v in values):
                out[r][c] = values[0]

    # Propagate values recovered from a repeated row to its transposed cell.
    for r in range(n):
        for c in range(n):
            if out[r][c] == 6 and out[c][r] != 6:
                out[r][c] = out[c][r]
    return out
'''
